"""Milestone 1 story plans, written by the director (Claude) following DIRECTOR.md, in a compact form.
Run from director/: python3 plans/_authoring_m1.py  -> writes plans/<name>.story_plan.json"""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
ORIG = {"story": "retold in our own words from public facts", "characters": "our own designs; no likeness traced from photos or other channels",
        "shots": "planned from the script, not copied from any existing video", "voice": "Kokoro synthetic voice (Apache-2.0 model)",
        "music": "must be a track with a recorded licence before delivery", "images": "generated or code-built; no downloaded photos"}
_n = [0]
def S(w0, typ, subject, action, shows=(), events=()):
    _n[0] += 1
    return {"id": f"sh{_n[0]:02d}", "w0": w0, "type": typ, "subject": subject, "action": action, "shows": list(shows), "events": list(events)}
def B(claim, fact, item, how, *shots):
    return {"id": f"b{shots[0]['id'][2:]}", "claim": claim, "fact": fact, "proof": {"item": item, "how": how}, "shots": list(shots)}
def C(cid, costume, holds=(), **kw): return {"id": cid, "costume": costume, "holds": list(holds), **kw}
def SC(sid, rel, reason, tag, place, time, cast, crowd, dressing, beats, timeline="main", props_here=(), empty_reason=None):
    d = {"id": sid, "relation": rel, "relation_reason": reason, "tag": tag, "timeline": timeline, "place": place, "time": time,
         "cast": cast, "crowd": crowd, "dressing": dressing, "props_here": list(props_here), "beats": beats}
    if empty_reason: d["empty_reason"] = empty_reason
    return d
def P(pid, kind, desc, period, public=False): return {"id": pid, "kind": kind, "desc": desc, "period": period, "public": public}
def F(fid, claim, status, url, note=""): return {"id": fid, "claim": claim, "status": status, "url": url, "note": note}
def give(p, a, b): return {"do": "give", "prop": p, "from": a, "to": b}
def ev(do, p, who): return {"do": do, "prop": p, "who": who}
def write(name, plan):
    json.dump(plan, open(os.path.join(HERE, name + ".story_plan.json"), "w"), indent=1); _n[0] = 0

